const D = { energy: .6, scale: 1, density: .55, speed: 1, haze: .55, wet: .6, hue: 28, x: .5, y: .58, style: 'lantern', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- A rice-paper lantern night market seen down its length: rows of stalls telescope into
// warm haze, catenary lantern strings sway at every depth, steam lifts off the food carts, and
// the whole scene is doubled in the wet stone underfoot. Depth is carried by parallax: near
// stalls slide fast and warm, far ones creep and drown in atmosphere. ----
const u = Math.min(width, height);
const hu = h => ((h % 360) + 360) % 360;
const fr = i => { let h = (Math.imul(i|0, 374761393) + Math.imul(P.seed|0, 2246822519) + 3266489917) | 0; h = Math.imul(h ^ (h >>> 15), 2246822519); return ((h ^ (h >>> 13)) >>> 0) / 4294967295; };
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const ho = P.hue - 28;

const STY = {
  // paper-lantern night: deep teal-navy sky, warm amber & vermilion lanterns, wet amber ground
  lantern: { sky:[212,64,10], glow:[30,70,42], lant:[32,86,100], lant2:[8,88,96], stall:[220,50,9], stallLit:[34,60,44], grd:[26,66,20], flat:0, ink:0, steam:1 },
  // Hopper nocturne: cool desaturated, one warm sodium key, austere and quiet
  noir:    { sky:[214,40,7],  glow:[36,34,30], lant:[40,44,86],  lant2:[30,50,80], stall:[216,26,8], stallLit:[40,30,34], grd:[214,22,15], flat:0, ink:0, steam:.6 },
  // ukiyo-e woodblock: flat indigo + vermilion, carved tonal bands, paper grain
  ukiyo:   { sky:[224,70,16], glow:[16,72,50], lant:[14,84,96],  lant2:[38,80,94], stall:[228,58,12], stallLit:[20,60,50], grd:[18,64,26], flat:1, ink:0, steam:.5 },
  // ember night: hot smoky reds & oranges, heavy steam, deep and close
  ember:   { sky:[344,52,9],  glow:[18,80,44], lant:[24,92,100], lant2:[2,90,92],  stall:[350,50,8], stallLit:[22,70,42], grd:[14,80,22], flat:0, ink:0, steam:1.3 },
  // ABSTRACTED sumi: warm-grey tonal wash, lanterns as soft ink halos, no local colour
  ink:     { sky:[30,10,14],  glow:[30,22,40], lant:[34,30,92],  lant2:[30,34,86], stall:[30,10,10], stallLit:[32,18,40], grd:[30,14,22], flat:0, ink:1, steam:.8 }
};
const st = STY[P.style] || STY.lantern;
const sky = [hu(st.sky[0]+ho), st.sky[1], st.sky[2]];
const en = Math.max(0, Math.min(1, P.energy));
const NL = 5;                                    // depth planes, 0 = farthest
const gy = height * P.y;                          // the ground line / waterline
const key = [width, height, P.style, P.seed, Math.round(P.hue), P.scale.toFixed(2), P.density.toFixed(2)].join('|');

if (!S.sky || S.key !== key) {
  if (S.sky) { S.sky.remove(); if (S.str) S.str.forEach(o => o.g.remove()); }
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  const mk = (w, h) => { const g = createGraphics(Math.max(2, Math.ceil(w)), Math.max(2, Math.ceil(h))); g.colorMode(g.HSB, 360, 100, 100, 100); g.noStroke(); return g; };

  // sky + haze gradient: dark navy zenith down to a warm sodium glow pooling at the market floor
  S.sky = mk(W, H);
  const g = S.sky; const glow = [hu(st.glow[0]+ho), st.glow[1], st.glow[2]];
  for (let yy = 0; yy < H; yy++) {
    let c;
    if (yy < gy) { const f = Math.pow(Math.min(1, yy/Math.max(1,gy)), .8); c = L3(glow, sky, f*.86); }
    else { const f = Math.min(1, (yy-gy)/Math.max(1,H-gy)); c = L3([hu(st.grd[0]+ho),st.grd[1],st.grd[2]], [hu(st.grd[0]+ho),st.grd[1]*.7,st.grd[2]*.4], f); }
    g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1);
  }

  // stall silhouette strata: rooftops + awnings + posts, tileable, near = big/warm/low
  S.str = [];
  const stall = [hu(st.stall[0]+ho), st.stall[1], st.stall[2]];
  const sLit = [hu(st.stallLit[0]+ho), st.stallLit[1], st.stallLit[2]];
  for (let j = 0; j < NL; j++) {
    const f = (j + 1) / NL;                       // 0..1 nearness
    const haze = (1 - f) * .72;
    const bh = Math.max(6, Math.ceil(u * (.16 + f * .40) * P.scale));
    const q = mk(W, bh);
    const baseC = L3(stall, glow, haze);
    const litC = L3(sLit, glow, haze * .7);
    const nStall = Math.max(2, Math.round((3 + f * 4) * (.6 + P.density)));
    for (let s = 0; s < nStall; s++) {
      const sx = (s + fr(j*40+s*3)*.5) * (W / nStall);
      const sw = (W / nStall) * (.62 + fr(j*40+s*3+1) * .5);
      const rh = bh * (.34 + fr(j*40+s*3+2) * .4);
      // awning roof (pitched or curved pagoda-ish sweep)
      q.fill(baseC[0], baseC[1], baseC[2] * (.7 + fr(s+j)*.4), st.flat ? 100 : 94);
      q.beginShape();
      q.vertex(sx - sw*.05, bh);
      q.vertex(sx - sw*.05, bh - rh);
      const swp = fr(j*40+s*3+4) * .5;
      q.quadraticVertex(sx + sw*.5, bh - rh - u*.02*(1+swp)*P.scale, sx + sw*1.05, bh - rh);
      q.vertex(sx + sw*1.05, bh);
      q.endShape(q.CLOSE);
      // lit under-eave line (warm rim from the lanterns beneath)
      q.fill(litC[0], litC[1]*.8, Math.min(100, litC[2] + 18), (30 + 40*f) * (1 - st.ink*.4));
      q.rect(sx - sw*.05, bh - rh, sw*1.1, u*.006*P.scale*(0.6+f));
      // stall posts
      q.fill(baseC[0], baseC[1], baseC[2]*.55, 90);
      q.rect(sx, bh - rh*.5, u*.006*P.scale*(.5+f), rh*.6);
      q.rect(sx + sw, bh - rh*.5, u*.006*P.scale*(.5+f), rh*.6);
    }
    if (st.ink) { // wash grain for the ink style
      for (let i = 0; i < 200; i++) { q.fill(30, 8, fr(i*7+j)>.5?30:6, 4); q.rect(fr(i*3+j)*W, fr(i*3+j+1)*bh, u*.003, u*.003); }
    }
    S.str.push({ g: q, f: f, rate: u * .0016 * Math.pow(f, 1.4), yBase: gy - bh + u*.004 });
  }
  S.key = key;
}

// ---------------- draw ----------------
noStroke();
image(S.sky, 0, 0);

const scrX = (g, px, yy) => { const W2 = g.width; const ox = ((px % W2) + W2) % W2; image(g, ox - W2, yy); image(g, ox, yy); };
const bob = Math.sin(K.t*.043) * u*.004 + Math.sin(K.t*.017+1.1) * u*.006;   // slow lateral market breath

// far -> near stall strata with continuous parallax scroll
for (let j = 0; j < NL; j++) {
  const s = S.str[j];
  scrX(s.g, -K.t * s.rate * P.speed * 22 * (1 + s.f) + bob * (0.3 + s.f), s.yBase);
}

// ---------------- lantern strings + steam + reflections, drawn live ----------------
const lant = [hu(st.lant[0]+ho), st.lant[1], st.lant[2]];
const lant2 = [hu(st.lant2[0]+ho), st.lant2[1], st.lant2[2]];
const drawLantern = (lx, ly, r, c, br, refl) => {
  // soft warm bloom
  blendMode(ADD);
  for (let k = 3; k >= 0; k--) { fill(c[0], c[1]*(.7-k*.12), c[2], (6 + 16*br)*(1-k*.2)*(refl?.5:1)); ellipse(lx, ly, r*(1.4+k*2.4), r*(1.6+k*2.6)); }
  blendMode(BLEND);
  // the paper body
  fill(c[0], c[1]*(refl?.7:1), c[2]*(refl?.7:1)*(.7+br*.4), (refl?55:100));
  ellipse(lx, ly, r*1.1, r*1.5);
  fill(c[0], c[1]*.5, Math.min(100, c[2]+10), (refl?40:80));
  ellipse(lx - r*.18, ly - r*.2, r*.5, r*.7);   // hot core
};

for (let j = 0; j < NL; j++) {
  const f = (j + 1) / NL;
  const yline = gy - u * (.10 + f * .30) * P.scale + Math.sin(K.t*(.06+j*.02)+j)*u*.004;
  const nL = Math.max(3, Math.round((5 + f * 7) * (.5 + P.density)));
  const r = u * (.008 + f * .022) * P.scale;
  const sagAmp = u * (.03 + f*.05) * P.scale;
  const phase = K.t * (.10 + j*.03);
  for (let i = 0; i < nL; i++) {
    const t0 = (i + .5) / nL;
    const seg = Math.sin(t0 * Math.PI);           // catenary sag across the span
    const sway = Math.sin(K.t*(.5 + j*.13 + i*.017) + i*1.7) * u*.006*(.4+f)
               + Math.sin(K.t*(.23 + j*.07) + i*.9) * u*.004*(.4+f);
    const lx = (t0 * width) + sway + Math.sin(phase + i)*u*.003;
    const ly = yline + seg*sagAmp + Math.sin(K.t*(.7+i*.05)+j)*u*.003;
    const flick = .7 + .3*Math.sin(K.t*(1.1+fr(i*3+j*7)*1.6) + i) + K.pulse*.12 + A.mid*.3;
    const c = (i + j) % 3 === 0 ? lant2 : lant;
    drawLantern(lx, ly, r, c, en*flick, false);
    // wet-stone reflection, mirrored below the ground line, wavering
    if (P.wet > .02 && ly < gy) {
      const ry = gy + (gy - ly) * (.7 + .3*P.wet) + Math.sin(K.t*(1.3+i*.2)+j)*u*.01;
      const rx = lx + Math.sin(K.t*(.9+i*.15))*u*.006;
      drawLantern(rx, ry, r*(.9+.2*P.wet), c, en*flick*P.wet*.8, true);
    }
  }
}

// steam plumes lifting off the carts — broad, soft, drifting (carries the motion floor)
const nS = Math.round((6 + P.density*14) * st.steam);
blendMode(ADD);
for (let i = 0; i < nS; i++) {
  const life = ((K.t * (.05 + fr(i*3+40)*.06) * P.speed + fr(i*3+41)) % 1);
  const bx = fr(i*3+42) * width + Math.sin(K.t*(.3+i*.1)+i)*u*.02;
  const by = gy - u*.02 - life * u * (.4 + fr(i*3+43)*.5) * P.scale;
  const sz = u * (.05 + life*.14 + fr(i*3+44)*.06) * P.scale;
  const fade = Math.sin(Math.PI*Math.min(1,life*1.1)) * P.haze;
  fill(hu(st.glow[0]+ho), 12, 92, (3 + 7*fade) * (.5+en*.6));
  ellipse(bx, by, sz*(1+.3*Math.sin(K.t+i)), sz*.8);
}
blendMode(BLEND);

// wet ground sheen: a warm horizontal glow band with soft vertical smears
if (P.wet > .02) {
  blendMode(ADD);
  for (let i = 0; i < 5; i++) { fill(hu(st.glow[0]+ho), 30, 60, 4*P.wet*(1-i*.15)); ellipse(width*P.x, gy + u*.02 + i*u*.01, width*1.1, u*(.06+i*.05)); }
  blendMode(BLEND);
}

// framing vignette so the eye settles down the market
for (let i = 0; i < 4; i++) { noFill(); strokeWeight(u*.05); stroke(sky[0], sky[1], 5, 16*(1-i*.2)); rect(-u*.02+i*u*.03, -u*.02+i*u*.03, width+u*.04-i*u*.06, height+u*.04-i*u*.06); }
noStroke();

if (P.alpha < 100) { fill(sky[0], sky[1]*.6, 5, (100-P.alpha)); rect(0,0,width,height); }
drawingContext.shadowBlur = 0;
